"""Cash advances: requested ahead of a trip, approved and paid like a report, then settled against the report that follows."""
from dataclasses import dataclass, replace
from enum import Enum
from typing import Optional, Sequence

from .errors import Failure, FailureCode
from .ids import Badge, DepartmentId, Money, Period

AdvanceId = str

MAX_APPROVALS = 2      # a third approval completes the chain, so a Requested advance never holds three


class AdvanceStatus(Enum):
    REQUESTED = "Requested"
    APPROVED = "Approved"
    PAID = "Paid"
    SETTLED = "Settled"


TRANSITIONS = {
    AdvanceStatus.REQUESTED: {AdvanceStatus.APPROVED},
    AdvanceStatus.APPROVED: {AdvanceStatus.PAID},
